import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2020-08-28","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-08-28","date":"2020-08-28T00:00:00.000Z","updated":"2020-08-28T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","CRUSH算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-08-28.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-08-28.md","lastUpdated":1780460162000}'),r={name:"posts/2020/Ceph_Performance_Meeting_2020-08-28.md"};function o(n,e,s,h,p,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph性能会议由于主持人迟到，开始时人数较少。会议主要讨论了Ceph项目的进展、待处理的Pull Requests（PRs）、性能回归问题以及未来的行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>PRs更新</strong></p><ul><li>会议讨论了本周关闭的一个PR，该PR旨在避免从machine ping一次性刷新过多数据，效果良好。</li><li>另一个PR由majianpeng更新，radik批准了减少buffer list重建的更改。</li></ul></li><li><p><strong>性能回归问题</strong></p><ul><li>Igor提到了最近关于性能回归的发现，特别是在某些场景下的改进，可能需要回溯到Octopus版本。</li><li>讨论了max blob size的更改原因及其对性能的影响，特别是对搜索范围和压缩的影响。</li></ul></li><li><p><strong>未来行动计划</strong></p><ul><li>计划在下周与Adam和Gabriel讨论关于简化数据结构和减少内存占用的想法。</li><li>讨论了关于性能CI的构建，包括使用cbt和jenkins进行自动化测试的可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了需要进一步讨论和测试的PRs。</li><li>确定了下周的会议将讨论数据结构简化和其他相关性能优化。</li><li>计划开始构建性能CI，以自动化和标准化性能测试。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Igor和Mark将撰写关于当前CI系统中性能测试的概述，并发送至开发列表。</li><li>继续关注和讨论性能回归问题，并尝试在不同环境中复现。</li><li>探索和实施性能CI的构建，以确保性能测试的自动化和一致性。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了关于硬件配置对性能测试的影响，特别是SSD和HDD的使用。</li><li>提到了关于压缩和blob size的优化，以及这些更改可能带来的复杂性和潜在影响。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了性能测试和CI构建的重要性后结束，主持人因时间限制提前离开。</p><p>本次会议虽然人数不多，但讨论的内容非常深入和具体，涉及到了Ceph项目的多个关键技术点和未来的发展方向。通过这次会议，团队对当前的工作有了更清晰的认识，并为接下来的工作制定了具体的行动计划。</p>',14)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
